{
  "per_column": [
    {
      "name": "staff_interaction_quality",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.55,
      "hallucination_observed": true,
      "rationale": "A genuine categorical axis (friendly/rude/indifferent/mixed) that adds qualitative nuance beyond the numeric Staff Service rating and helps surface a key theme. However, groundedness is compromised: in the row about dreadful seats/headphones the text says nothing about crew, yet the column asserts 'unhelpful_indifferent'. The near-total absence of NULLs (only 20) signals values are being forced onto rows where staff is not mentioned, i.e. inferred from overall tone rather than read from source."
    },
    {
      "name": "food_quality_assessment",
      "analytical_usefulness": 0.78,
      "source_groundedness": 0.62,
      "hallucination_observed": true,
      "rationale": "Useful thematic decomposition with a nice granular value ('dietary_request_failed') and correct use of NULL for silent rows (e.g. the 'consistently good service' review is left null). But the seat/headphone review that never mentions food is coded 'poor_bland', an invented negative. Grounded where food is discussed, hallucinated where it is not."
    },
    {
      "name": "service_consistency_trend",
      "analytical_usefulness": 0.62,
      "source_groundedness": 0.68,
      "hallucination_observed": false,
      "rationale": "Detecting 'declining_vs_past' / 'improving' is a legitimately interesting axis for spotting eroding service, so it adds leverage. Weakness is that ~70% collapse to the catch-all 'first_time_no_baseline', which is a reasonable default when the text gives no comparative signal (as in the samples), so it is not a hallucination but the column's analytical bite is limited to the minority of comparative reviews."
    },
    {
      "name": "cabin_product_type",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.6,
      "hallucination_observed": true,
      "rationale": "Product-level granularity (lieflat vs recliner business, qsuite, premium economy) is a good grouping axis that goes beyond the raw Class column. Groundedness is uneven: the 1h45 Jakarta-Singapore review that only mentions legroom/IFE is labelled 'new_business_lieflat', an unsupported specific, while the economy 3-3-3 review is correctly 'standard_economy'. Some values appear inferred beyond what the text supports."
    },
    {
      "name": "disruption_handling_quality",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "Captures how delays/cancellations were handled, a high-value concentration point (2321 'inadequate_poor'). Correctly uses 'not_applicable' for the many reviews with no disruption, matching all five samples where no disruption is mentioned. Sound grounding."
    },
    {
      "name": "ground_service_experience",
      "analytical_usefulness": 0.75,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "Separates check-in/boarding sentiment from inflight, a distinct and useful axis. Appropriately NULL for the silent sample rows. Values look like sound readings of source text where present."
    },
    {
      "name": "customer_service_resolution",
      "analytical_usefulness": 0.7,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "Complaint-resolution outcome is analytically relevant, though it partially overlaps in spirit with disruption_handling and booking_policy. Uses 'no_complaint' default sensibly; the samples (no complaints raised) are correctly coded. Well grounded."
    },
    {
      "name": "booking_policy_issue",
      "analytical_usefulness": 0.7,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "Enumerates concrete policy pain points (rebooking, refunds denied, lost seat reservations) — a useful axis for operational focus. Default 'no_issue' is applied correctly to the samples, including the emergency-exit-seat review which mentions booking but no policy dispute. Grounded."
    },
    {
      "name": "haul_type",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.95,
      "hallucination_observed": false,
      "rationale": "A clean, high-leverage grouping dimension deterministically derivable from Route. All five samples (Jakarta-Singapore short, Singapore-London long, etc.) are classified correctly. Strong on both dimensions."
    }
  ],
  "analytical_usefulness": 0.77,
  "source_groundedness": 0.73,
  "rationale": "Collectively the added columns form a rich thematic decomposition of the free-text reviews (staff, food, ground service, disruption handling, complaint resolution, booking issues, cabin product, haul type), directly serving the 'what should I concentrate on' query by giving multiple genuine axes to group and compare on that go beyond the existing numeric ratings. Usefulness is solid overall. Groundedness is generally good — the complaint/handling/ground/booking columns correctly use 'not_applicable'/NULL for silent rows, and haul_type is deterministically routable — but there is a recurring hallucination pattern in the more subjective columns: a review mentioning only seats/entertainment was assigned negative staff ('unhelpful_indifferent') and negative food ('poor_bland'), and a short domestic hop was labelled 'new_business_lieflat'. These forced/over-specified values, plus the near-zero NULL count in staff_interaction_quality, pull the table-level groundedness down from otherwise strong."
}

